#define PB_PINS_HEADER "pb_pins_test.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include "../../src/pb_core.h"
static unsigned now_ms,writes; static uint16_t outs[4],pads[4]; static char output[32768]; static size_t used;
static int mode(void*x,unsigned p,unsigned b,unsigned m,unsigned l){(void)x;(void)m;if(l)outs[p]|=(uint16_t)(1u<<b);else outs[p]&=(uint16_t)~(1u<<b);return 0;}
static void wr(void*x,unsigned p,uint16_t mask,uint16_t val){(void)x;outs[p]=(uint16_t)((outs[p]&~mask)|(val&mask));writes++;}
static uint16_t rd(void*x,unsigned p){(void)x;return (uint16_t)(pads[p]|outs[p]);}
static int adc(void*x,int ch,unsigned*r,unsigned*m){(void)x;(void)ch;if(!r||!m)return -1;*r=412;*m=1219;return 0;}
static uint32_t ms(void*x){(void)x;return now_ms;}
static int tx(void*x,const char*s,size_t n){(void)x;if(n>sizeof(output)-used-1)return 0;memcpy(output+used,s,n);used+=n;output[used]=0;return 1;}
static void fail(unsigned line,const char*msg){fprintf(stderr,"line %u: %s (pending output: %s)\n",line,msg,output);exit(1);}
static void consume(unsigned line,const char*expect){size_t n=strlen(expect);if(used<n||memcmp(output,expect,n)|| (used>n&&output[n]!='\n'))fail(line,"reply mismatch");if(used==n){output[0]=0;used=0;}else{memmove(output,output+n+1,used-n-1);used-=n+1;output[used]=0;}}
int main(int argc,char**argv){pb_core c;pb_hal h={0,mode,wr,rd,adc,0,ms,tx};FILE*f;char line[2048];unsigned ln=0;if(argc!=2){fprintf(stderr,"usage: pb_test transcript\n");return 2;}f=fopen(argv[1],"r");if(!f){perror(argv[1]);return 2;}pb_init(&c,&h);while(fgets(line,sizeof line,f)){char *s,*e;ln++;s=line;while(*s&&isspace((unsigned char)*s))s++;e=s+strlen(s);while(e>s&&isspace((unsigned char)e[-1]))*--e=0;if(!*s||*s=='#')continue;if(*s=='<'){if(s[1]!=' ')fail(ln,"bad expected directive");char exp[512];snprintf(exp,sizeof exp,"%s",s+2);char *p=strstr(exp,"{cfg}");if(p){memmove(p+8,p+5,strlen(p+5)+1);memcpy(p,"583900e4",8);}p=strstr(exp,"{int}");if(p){memmove(p+1,p+5,strlen(p+5)+1);*p='0';}if(!strchr(exp,'\n'))strcat(exp,"\n");consume(ln,exp);continue;}if(*s=='>'){int cr=s[1]=='r';char *cmd=s+(cr?3:2);if(s[1]!=' '&&!cr)fail(ln,"bad send directive");if(cr&&s[2]!=' ')fail(ln,"bad CRLF directive");pb_rx(&c,(const unsigned char*)cmd,strlen(cmd));if(cr)pb_rx(&c,(const unsigned char*)"\r",1);pb_rx(&c,(const unsigned char*)"\n",1);continue;}if(*s=='@'){unsigned a,b;char pin[16],val[16];if(sscanf(s,"@time %u",&a)==1){now_ms=a;continue;}if(sscanf(s,"@advance %u",&a)==1){for(b=0;b<a;b+=10){now_ms+=10;pb_poll(&c);}continue;}if(sscanf(s,"@pad %15[^=]=%15s",pin,val)==2){int i=pb_pin(pin);if(i<0)fail(ln,"unknown @pad pin");unsigned p=pb_defs[i].port,bit=pb_defs[i].bit;if(!strcmp(val,"1"))pads[p]|=(uint16_t)(1u<<bit);else if(!strcmp(val,"0"))pads[p]&=(uint16_t)~(1u<<bit);else fail(ln,"bad @pad value");continue;}if(sscanf(s,"@hw %15s",pin)==1){char *q=strchr(s,' ')+1;while(*q){char name[16],state[16];int n=0;if(sscanf(q,"%15[^=]=%15s%n",name,state,&n)!=2)break;int i=pb_pin(name);if(i<0)fail(ln,"unknown @hw pin");unsigned p=pb_defs[i].port,bit=pb_defs[i].bit;unsigned m=(c.pins[i].mode);if(!strcmp(state,"hi")&&!(outs[p]&(1u<<bit)))fail(ln,"@hw expected hi");if(!strcmp(state,"lo")&&(outs[p]&(1u<<bit)))fail(ln,"@hw expected lo");if(!strcmp(state,"in")&&m!=PB_IN&&m!=PB_UP&&m!=PB_DN&&m!=PB_HIZ)fail(ln,"@hw expected input");q+=n;while(*q==' ')q++;}continue;}if(sscanf(s,"@writes %u",&a)==1){if(writes!=a)fail(ln,"write_port call count mismatch");writes=0;continue;}if(!strncmp(s,"@reboot",7)){pb_init(&c,&h);continue;}if(!strncmp(s,"@config test",12)||!strncmp(s,"@config real",12))continue;if(!strncmp(s,"@send ",6)){char raw[512];if(sscanf(s+6,"\"%511[^\"]\"",raw)!=1)fail(ln,"bad @send");pb_rx(&c,(unsigned char*)raw,strlen(raw));continue;}if(sscanf(s,"@long %u",&a)==1){char big[1024];if(a>900)fail(ln,"@long too large");memset(big,'x',a);big[a]='\n';pb_rx(&c,(unsigned char*)big,a+1);continue;}fail(ln,"unknown directive");}fail(ln,"unknown transcript line");}fclose(f);if(used)fail(ln,"unexpected extra output");printf("PASS %s\n",argv[1]);return 0;}
